if(restoredSave.blocked){canSave=false;$('notice').textContent='이전 저장을 복원하지 못해 원본을 보호하고 자동 저장을 멈췄습니다. 저장·복원에서 백업을 불러오거나 원본을 받아 주세요.';$('notice').hidden=false;}
const coords={GK:[[50,88]],...F.formationPositions},labels={press:'몰아붙이기',balanced:'균형 유지',counter:'내려서 역습',lowBlock:'로우 블록'};
