 $('league-table').innerHTML=`<div class="panel-heading"><h2>${tier.name}</h2><button type="button" class="text-button" data-open-league>전체 순위·라운드 결과 →</button></div><div class="table-wrap"><table class="league-table"><thead><tr><th>순위</th><th>구단</th><th>경기</th><th>득실</th><th>승점</th></tr></thead><tbody>${table.map(c=>`<tr class="${c.id===S.own?'own-row':''} ${leagueZone(c)?.kind||''}-row"><td>${c.rank}${leagueZone(c)?'<small class="league-zone '+leagueZone(c).kind+'">'+leagueZone(c).label+'</small>':''}</td><th scope="row">${clubMark(c)}<span>${c.short}</span></th><td>${c.played}</td><td>${c.gd>0?'+':''}${c.gd}</td><td><b>${c.points}</b></td></tr>`).join('')}</tbody></table></div><p class="table-note">${leagueRulesLabel(season)} · 승리 3점 · 무승부 1점<br>동률은 득실차, 득점, 구단명 순으로 결정합니다.</p>`;
