function renderSquadOverview(){
 const keyNames={keeping:'선방',defense:'수비',passing:'패스',attack:'결정력'};
 $('squad-overview').innerHTML=`<div class="squad-title"><div class="eyebrow">PLAYER DEVELOPMENT</div><h2>선수 성장 기록</h2><p>능력 훈련은 건강한 선수에게, 경험은 출전한 선수에게 쌓입니다.<br>출전 270분마다 주요 능력 +1 · 선수마다 다른 성장 한계</p></div><div class="table-wrap"><table class="squad-table"><thead><tr><th>선수</th><th>역할</th><th>주요 능력</th><th>성장 한계</th><th>주급</th><th>속도</th><th>체력</th><th>출전 상태</th><th>성장 경험</th></tr></thead><tbody>${Object.values(season.squad).map(p=>{const key=S.primaryKey(p),base=F.identityProfile(p.identity),delta=p[key]-base[key],energy=state?state.players[p.id].energy:p.energy;return `<tr><th scope="row"><span class="squad-number">${p.no}</span><button class="roster-profile-button" data-player-detail="${playerUiText(p.identity)}" aria-label="${playerUiText(p.name)} 선수 상세 보기">${Portraits.html(p)}<span class="squad-player-name">${playerUiText(p.name)}</span><span class="profile-arrow" aria-hidden="true">↗</span></button>${p.academy?'<small class="graduate-label">센터 출신</small>':''}</th><td>${p.pos}</td><td><small>${keyNames[key]}</small> ${p[key]}${delta?'<em>+'+delta+'</em>':''}</td><td>${p.potential}</td><td>${moneyLabel(p.wage)}</td><td>${p.speed}</td><td><span class="energy-value ${energy<50?'low':''}">${Math.round(energy)}</span></td><td>${fitnessBadge(p)}</td><td><span class="xp-track"><i style="width:${p.xp%270/270*100}%"></i></span><small>${p.xp%270} / 270분</small></td></tr>`;}).join('')}</tbody></table></div>`;
}
function save(){canSave=saveRecovery.save(currentCampaignPayload());}
function escapeText(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function notify(text){$('notice').textContent=text;$('notice').hidden=false;if(typeof showMatchPopupError==='function')showMatchPopupError(text);}
function action(fn){try{fn();if(state===season.match)S.applySetPiecePlan(season);$('notice').hidden=true;save();render();}catch(err){notify(err.message);}return snapshot();}
function snapshot(){if(!state)return {phase:'season-complete',year:season.year,league:season.league,movement:S.movement(season),table:S.standings(season)};return {year:season.year,league:season.league,round:season.round+1,competition:season.competition,cupStage:season.competition==='cup'?P.stageNames[season.cup.stage]:null,europeStage:season.competition==='europe'?Europe.stageNames[season.europe.stage]:null,phase:state.phase,minute:state.minute,paused:state.paused,playback:{...playbackPrefs},score:state.score,tactic:state.tactic,formation:state.formation,subsUsed:state.subs,lineupPlan:{roles:{...tacticalRoles},positions:{...customPositions}},lineup:state.lineup.map(id=>({id,name:state.players[id].name,pos:state.players[id].pos,energy:Math.round(state.players[id].energy)})),bench:Object.values(state.players).filter(p=>!state.lineup.includes(p.id)&&!state.out.includes(p.id)).map(p=>({id:p.id,name:p.name,pos:p.pos,speed:p.speed,energy:Math.round(p.energy),injuryRemaining:p.injuryRemaining||0,suspended:!!p.suspended}))};}
function metric(p){return p.pos==='GK'?'선방 '+p.keeping:p.pos==='DEF'?'수비 '+p.defense:p.pos==='MID'?'패스 '+p.passing:'결정력 '+p.attack;}
const playerRoleOptions={GK:[['goalkeeper','골키퍼'],['sweeperKeeper','스위퍼 키퍼']],DEF:[['centralDefender','중앙 수비수'],['ballPlayingDefender','볼 플레이잉 수비수'],['wingBack','윙백']],MID:[['centralMidfielder','중앙 미드필더'],['deepLyingPlaymaker','딥라잉 플레이메이커'],['boxToBox','박스 투 박스'],['advancedPlaymaker','공격형 플레이메이커']],FW:[['advancedForward','어드밴스드 포워드'],['deepLyingForward','딥라잉 포워드'],['poacher','포처'],['targetForward','타깃 포워드']]};
const roleDepth={goalkeeper:88,sweeperKeeper:82,centralDefender:72,ballPlayingDefender:67,wingBack:61,centralMidfielder:49,deepLyingPlaymaker:59,boxToBox:47,advancedPlaymaker:37,advancedForward:22,deepLyingForward:34,poacher:14,targetForward:20};
const roleDescriptions={goalkeeper:'골문을 지키는 기본 역할',sweeperKeeper:'수비 뒤 공간까지 먼저 처리',centralDefender:'수비 라인을 안정적으로 유지',ballPlayingDefender:'후방에서 패스로 전개',wingBack:'측면을 넓게 쓰며 전진',centralMidfielder:'중앙에서 공수 균형 유지',deepLyingPlaymaker:'낮은 위치에서 경기를 조율',boxToBox:'양쪽 페널티 지역을 왕복',advancedPlaymaker:'공격진 가까이에서 기회 창출',advancedForward:'수비 뒷공간으로 침투',deepLyingForward:'내려와 연계하는 공격수',poacher:'골문 앞 득점에 집중',targetForward:'높은 위치에서 공을 지켜 연계'};
const roleWeights={goalkeeper:{keeping:.8,passing:.1,defense:.1},sweeperKeeper:{keeping:.55,passing:.25,speed:.2},centralDefender:{defense:.75,endurance:.15,passing:.1},ballPlayingDefender:{defense:.5,passing:.35,speed:.15},wingBack:{speed:.4,endurance:.35,passing:.15,defense:.1},centralMidfielder:{passing:.45,endurance:.25,defense:.15,attack:.15},deepLyingPlaymaker:{passing:.6,defense:.2,endurance:.2},boxToBox:{endurance:.4,speed:.2,passing:.2,attack:.1,defense:.1},advancedPlaymaker:{passing:.55,attack:.25,speed:.1,endurance:.1},advancedForward:{attack:.55,speed:.35,passing:.1},deepLyingForward:{attack:.4,passing:.4,endurance:.2},poacher:{attack:.75,speed:.2,passing:.05},targetForward:{attack:.55,endurance:.3,passing:.15}};
function roleSuitability(p,key){return Math.round(Object.entries(roleWeights[key]).reduce((score,[stat,weight])=>score+(p[stat]||0)*weight,0));}
function bestPlayerRole(p){return playerRoleOptions[p.pos].map(([key,label])=>({key,label,score:roleSuitability(p,key)})).sort((a,b)=>b.score-a.score||a.label.localeCompare(b.label,'ko'))[0];}
function playerRole(p){const options=playerRoleOptions[p.pos],key=tacticalRoles[p.identity];return options.find(option=>option[0]===key)||options[0];}
function positions(){let idx={GK:0,DEF:0,MID:0,FW:0};return state.lineup.map(id=>{const p=state.players[id],base=p.pos==='GK'?coords.GK[0]:coords[state.formation][p.pos][idx[p.pos]++],saved=customPositions[p.identity],xy=Array.isArray(saved)&&saved.length===2&&saved.every(Number.isFinite)?saved:base;return {id,p,x:xy[0],y:xy[1]};});}
function renderMobileTacticsDock(){const host=$('mobile-tactics-dock');if(!host||!state)return;const energy=state.lineup.reduce((sum,id)=>sum+state.players[id].energy,0)/state.lineup.length,tired=state.lineup.filter(id=>state.players[id].energy<50).length,assigned=state.lineup.filter(id=>Object.hasOwn(tacticalRoles,state.players[id].identity)).length,roleFit=Math.round(state.lineup.reduce((sum,id)=>sum+roleSuitability(state.players[id],playerRole(state.players[id])[0]),0)/state.lineup.length);host.innerHTML=`<div class="mobile-tactics-head"><span><small>전술 플랜</small><b>${state.formation.split('').join('-')} · ${labels[state.tactic]}</b></span><span>평균 체력 <b>${Math.round(energy)}</b>${tired?` · 주의 ${tired}`:''}</span></div><div class="mobile-shape-control" role="group" aria-label="포메이션 선택">${Object.keys(F.formations).map(shape=>`<button type="button" data-mobile-formation="${shape}" aria-pressed="${shape===state.formation}" ${state.phase!=='prep'?'disabled':''}>${shape.split('').join('-')}</button>`).join('')}</div><div class="mobile-mentality-control" role="group" aria-label="팀 전술 선택">${[['counter','역습'],['balanced','균형'],['press','압박'],['lowBlock','로우 블록']].map(([key,label])=>`<button type="button" data-mobile-tactic="${key}" aria-pressed="${key===state.tactic}" ${!editable()||key==='lowBlock'&&state.version<7?'disabled':''}>${label}</button>`).join('')}</div><p>역할 적합도 ${roleFit} · ${assigned}명 직접 지정 · 선수를 눌러 역할·교체</p>`;}
function renderPitchPlayerTools(){const tools=$('pitch-player-tools'),swaps=$('pitch-swap-options'),p=selected&&state?.players[selected];if(!tools||!swaps)return;const show=!!p&&state.lineup.includes(p.id)&&editable();tools.hidden=!show;swaps.hidden=!show;if(!show){tools.innerHTML=swaps.innerHTML='';return;}const role=playerRole(p),fit=roleSuitability(p,role[0]),best=bestPlayerRole(p),substitution=F.substitutionRules(state),candidates=Object.values(state.players).filter(candidate=>candidate.pos===p.pos&&!state.lineup.includes(candidate.id)&&!state.out.includes(candidate.id)&&F.isAvailable(candidate));tools.innerHTML=`<div><span><b>${escapeText(p.name)}</b> 주 포지션 ${p.pos}의 역할</span><label><span class="sr-only">선수 역할</span><select id="player-role-select">${playerRoleOptions[p.pos].map(([key,label])=>{const score=roleSuitability(p,key);return `<option value="${key}" ${key===role[0]?'selected':''}>${label} · 적합도 ${score}${key===best.key?' · 추천':''}</option>`;}).join('')}</select></label><button type="button" id="reset-player-position">위치 초기화</button></div><div class="role-fit-summary"><span>현재 역할 적합도 <b>${fit}</b></span><button type="button" id="apply-recommended-role" ${best.key===role[0]?'disabled':''}><span>코치 추천</span><b>${best.label} ${best.score}</b></button></div><small><b>${role[1]}</b> · ${roleDescriptions[role[0]]}. 아래 전술 배치에서 선수를 선택하고 위치를 조정하세요.</small>`;swaps.innerHTML=`<span>교체 투입</span>${candidates.map(candidate=>`<button type="button" data-pitch-swap="${candidate.id}" ${F.running(state)&&state.minute===0||state.phase!=='prep'&&state.subs>=substitution.limit?'disabled':''}><b>${escapeText(candidate.name)}</b><small>${metric(candidate)} · 체력 ${Math.round(candidate.energy)}</small></button>`).join('')||'<small>교체 가능한 같은 포지션 선수가 없습니다.</small>'}`;const applyRole=key=>{tacticalRoles[p.identity]=key;save();render();};$('player-role-select').onchange=event=>applyRole(event.target.value);$('apply-recommended-role').onclick=()=>applyRole(best.key);$('reset-player-position').onclick=()=>{delete customPositions[p.identity];save();render();};}

function matchLogText(event){const scorer=event.scorerIdentity&&F.identityProfile(event.scorerIdentity);return Movement.commentary(event,state,Opposition.roster(S.opponentFor(season)))||S.displayText(F.displayText(event.text,scorer?[scorer]:state?.players));}
function renderPitch(){
 renderMobileTacticsDock();
 const live=F.running(state)&&!state.paused;
 $('players').classList.toggle('live',live);
 $('players').innerHTML=positions().filter(row=>typeof Discipline==='undefined'||!Discipline.dismissed(state).includes(row.id)).map(({id,p,x,y})=>{
  const form=PlayerTraits.condition(season,p),energy=Math.round(p.energy),level=energy>=65?'good':energy>=35?'medium':'low',position=F.assignedPosition(x,y,p.pos),natural=PlayerTraits.preferredPositions(p)[0];
  const label=`${p.name}, 주 위치 ${PlayerTraits.positions[natural][0]}, ${metric(p)}, 배치 ${position.code}, 체력 ${energy}, 컨디션 ${form.label}${form.score===null?'':' '+form.score}. ${typeof openMatchPopup==='function'?'경기 중계':'선발 선택'}`;
  return `<button class="player ${selected===id?'selected':''} ${p.energy<50?'tired':''}" data-player="${id}" aria-label="${escapeText(label)}" ${!editable()||typeof openMatchPopup==='function'?'disabled':''} style="left:${x}%;top:${y}%"><span class="player-head" style="--player-skin:${Portraits.skin(p)}" aria-hidden="true"></span><span class="player-legs" aria-hidden="true"><i></i><i></i></span><span class="player-face-marker" data-position="${p.pos}" aria-hidden="true">${Portraits.html(p)}<i>${p.no}</i></span><span class="player-stamina stamina-${level}" style="--stamina-level:${energy}%" aria-hidden="true"><i></i></span><span class="player-form form-${form.tier}" title="컨디션 ${escapeText(form.label)}" aria-hidden="true"></span><span class="player-name" title="${escapeText(p.name)}">${escapeText(p.name.split(' ').at(-1))}</span><span class="player-role">${position.code}</span></button>`;
 }).join('');
 renderPitchPlayerTools();drawField();
}function renderBench(){const players=Object.values(state.players).filter(p=>!state.lineup.includes(p.id)&&(!selected||p.pos===state.players[selected]?.pos));$('bench').innerHTML=players.map(p=>`<button class="bench-player ${selected&&state.players[selected].pos===p.pos?'eligible':''} ${state.out.includes(p.id)?'used':''} ${p.injuryRemaining>0?'injured-player':''}" data-bench="${p.id}" aria-label="${p.name}, ${p.pos}, ${metric(p)}, 속도 ${p.speed}, 체력 ${Math.round(p.energy)}${p.suspended?', 출전 정지':''}${p.injuryRemaining>0?', 부상으로 '+p.injuryRemaining+'경기 휴식':''}" ${!F.isAvailable(p)||state.out.includes(p.id)||!editable()||F.running(state)&&state.minute===0||state.phase!=='prep'&&state.subs>=F.substitutionRules(state).limit?'disabled':''}><span class="name-row">${Portraits.html(p)}<span class="position">${p.pos}</span><span>${p.name}</span>${p.suspended?'<span class="bench-injury">출전 정지</span>':''}${p.injuryRemaining>0?'<span class="bench-injury">부상 '+p.injuryRemaining+'경기</span>':''}${p.academy?'<span class="prospect">유소년</span>':p.kind==='유망주'?'<span class="prospect">유망주</span>':''}</span><span class="mini-stats"><span>${p.pos==='GK'?'선방 '+p.keeping:p.pos==='DEF'?'수비 '+p.defense:p.pos==='MID'?'패스 '+p.passing:'결정력 '+p.attack} · 속도 ${p.speed}</span><span>체력 ${Math.round(p.energy)}</span></span></button>`).join('');}
function render(){if(typeof syncMatchScreenMode==='function')syncMatchScreenMode();if(typeof renderAppShell==='function'){renderAppShell();if(!appSessionStarted)return;}renderSeason();renderManagerJourney();if(typeof renderMatchdayObjectives==='function')renderMatchdayObjectives();renderOwnerBoard();renderSuspensions();renderSeasonReview();renderSeasonCalendar();renderSquadPlans();if(typeof renderClubLife==='function')renderClubLife();if(typeof renderTeamTalk==='function')renderTeamTalk();if(typeof renderEurope==='function'&&view==='cup')renderEurope();if(typeof renderStaff==='function'&&view==='squad')renderStaff();renderCoachGuide();if(view==='club')renderVisuals();if(view!=='match')return;renderFeedbackControls();renderMovementControls();renderMatchControls();if(!state){renderMatchday();return;}const cupResult=cupOutcome();document.querySelector('.season-strip strong').textContent=season.competition==='europe'?'CHAMPIONS LEAGUE':season.competition==='cup'?S.divisionInfo(season).cupEn:S.divisionInfo(season).en;document.querySelector('.season-strip span').textContent=season.competition==='europe'?(season.europe.stage<6?'조별리그 · 홈과 원정 · 상위 2팀 진출':'단판 토너먼트 · 90분 무승부는 승부차기'):season.competition==='cup'?'단판 토너먼트 · 90분 무승부는 승부차기':season.league.division+'부 · 홈과 원정 '+S.roundCount(season)+'경기 · '+(season.league.division>1?'상위 2팀 승격':season.league.rules==='five-tier'?'강등 없음':'하위 2팀 강등');renderPitch();renderBench();$('formation').value=state.formation;$('formation').disabled=state.phase!=='prep';$('home-score').textContent=state.score[0];$('away-score').textContent=state.score[1];$('clock').textContent=state.phase==='prep'?'KICK OFF':state.phase==='full'?'FULL TIME':state.minute+"′";$('phase-label').textContent=(season.competition==='europe'?'CHAMPIONS LEAGUE / '+Europe.stageNames[season.europe.stage]:season.competition==='cup'?'CUP / '+P.stageNames[season.cup.stage]:'LEAGUE '+String(season.round+1).padStart(2,'0')+'R')+' / '+{prep:'경기 준비',first:'전반',half:'하프타임',second:'후반',late:'65분의 판단',third:'마지막 승부',full:'경기 결과'}[state.phase];$('match-status').textContent={prep:'당신의 선발을 정하세요',half:'후반을 바꿀 시간',late:'남은 25분, 감독의 판단',full:season.competition==='europe'?europeFullTimeLabel(cupResult):cupResult?(cupResult.winner===S.own?(season.cup.stage===2?S.club(S.own).short+' 컵 우승':S.club(S.own).short+' 다음 라운드 진출'):'컵 도전을 마쳤습니다'):state.score[0]>state.score[1]?S.club(S.own).name+' 승리':state.score[0]===state.score[1]?'무승부':'다음 도전을 준비하세요'}[state.phase]||(state.paused?'일시 정지':'경기 진행 중');$('selection-hint').textContent=selected?`${state.players[selected].name} · ${F.personality(state.players[selected]).nickname} · ${state.players[selected].pos} · ${metric(state.players[selected])} · 속도 ${state.players[selected].speed} · 체력 ${Math.round(state.players[selected].energy)}`:F.running(state)&&state.minute===0?'첫 1분부터 교체할 수 있어요. 전술 지시는 지금도 변경할 수 있습니다.':editable()?'경기장의 선수를 누른 뒤 같은 포지션 선수를 선택하세요.':'벤치 선수는 경기 중 언제든 투입할 수 있어요.';$('sub-count').textContent=state.phase==='prep'?Object.values(state.players).filter(p=>!state.lineup.includes(p.id)&&F.isAvailable(p)).length+'명 출전 가능':`${state.subs}/${F.substitutionRules(state).limit}명 교체`;$('tactic-timing').textContent=editable()?'지금 변경 가능':'현재 지시 유지';document.querySelectorAll('[data-tactic]').forEach(b=>{b.setAttribute('aria-pressed',b.dataset.tactic===state.tactic);b.disabled=!editable()||b.dataset.tactic==='lowBlock'&&state.version<7;});$('tactic-note').textContent={press:'공격 기회가 늘지만 체력 소모와 상대 역습 기회도 늘어납니다.',balanced:'전체 선수의 능력을 고르게 활용합니다.',counter:'빠른 공격수로 뒷공간을 노립니다. 전체 공격 횟수는 줄어듭니다.',lowBlock:'수비 간격을 좁혀 상대 찬스를 줄입니다. 우리 공격 기회도 감소합니다.'}[state.tactic];$('primary').textContent={prep:'이 선발로 경기 시작',first:state.paused?'이 지시로 경기 이어가기':'5분 빠르게 보기',half:'이 결정으로 후반 시작',second:state.paused?'이 지시로 경기 이어가기':'5분 빠르게 보기',late:'마지막 25분 시작',third:state.paused?'이 지시로 경기 이어가기':'5분 빠르게 보기',full:season.competition==='europe'?'챔피언스리그 결과 확정 · 다음 일정':season.competition==='cup'?'컵 결과 확정 · 다음 일정':'결과 확정 · 다음 일정'}[state.phase];$('pause').hidden=!F.running(state);$('pause').textContent=state.paused?'5분 진행하고 다시 판단':'멈추고 전술·교체';$('action-note').textContent=state.phase==='prep'?'전술·교체는 경기 중 언제든 · 진행 자동 저장':F.running(state)?'멈추고 판단하거나, 5분씩 빠르게 볼 수 있어요.':state.phase==='full'?(season.competition==='europe'?'결과를 확정하면 챔피언스리그 순위·대진, 상금과 선수 성장에 반영됩니다.':season.competition==='cup'?'결과를 확정하면 컵 대진, 상금과 선수 성장에 반영됩니다.':'결과를 확정하면 리그 순위와 선수 성장에 반영됩니다.'):'같은 포지션끼리 경기당 최대 '+F.substitutionRules(state).limit+'명 교체';$('pitch-hint').textContent=state.phase==='prep'?'막대 체력 · 점 컨디션 · 배치는 전술 창에서':editable()?'막대 체력 · 점 컨디션 · 교체와 배치는 팝업에서':'막대 체력 · 점 컨디션 · 핵심 장면 중계';const latest=state.logs.at(-1);if(!latest){$('commentary').querySelector('.minute-label').textContent='감독실';$('commentary').querySelector('p').textContent=S.opponentFor(season).style+'. 선발과 전술을 정하세요.';}if(latest){$('commentary').querySelector('.minute-label').textContent=latest.minute+"′";$('commentary').querySelector('p').textContent=matchLogText(latest);}$('timeline').innerHTML=state.logs.filter(l=>l.type!=='break'&&l.type!=='start').slice(-7).reverse().map(l=>`<div class="event ${l.type==='goal'?'goal':''}"><b>${l.minute}′</b><span>${escapeText(matchLogText(l))}</span></div>`).join('');if(!canSave)$('action-note').textContent=saveRecovery.isBlocked()?'저장 원본 보호 중 · 저장·복원에서 이어갈 구단을 확인해 주세요. 임시 진행은 저장되지 않습니다.':'저장 불가 · 창을 닫으면 진행이 사라질 수 있어요.';renderReport();$('open-match-review').hidden=state.phase!=='full';$('results').hidden=state.phase!=='full';if(state.phase==='full')renderResults();renderMatchday();if(matchdayTab==='analysis')renderTacticsBoard();if(typeof renderMatchPopup==='function')renderMatchPopup();if(typeof syncMovementCommentary==='function')syncMovementCommentary();if(typeof syncMovementScore==='function')syncMovementScore();}
function renderReport(){const opp=S.opponentFor(season),r=F.ratings(state),slow=opp.speed<60;let heading=state.phase==='prep'?opp.short+' 전력':state.phase==='full'?'경기 종료':'선수 컨디션';let text=opp.style+'. '+(slow?'빠른 공격수의 침투가 기회를 만들 수 있습니다.':'기회를 늘릴지, 수비를 지킬지 판단하세요.');if(editable()&&state.phase!=='prep'){const tired=state.lineup.map(id=>state.players[id]).sort((a,b)=>a.energy-b.energy)[0];text=tired.name+'의 체력 '+Math.round(tired.energy)+'. 남은 교체는 '+Math.max(0,F.substitutionRules(state).limit-state.subs)+'명입니다.';}if(state.phase==='full')text='아래 경기 기록을 확인하고 결과를 확정하면 다음 일정으로 넘어갑니다.';$('opponent').querySelector('h1').textContent=heading;$('opponent').querySelector('p').textContent=text;$('opponent').querySelector('.report-facts').innerHTML=state.phase==='prep'?'<span>공격 <b>'+opp.attack+'</b></span><span>수비 속도 <b>'+opp.speed+'</b></span>':'<span>공격 기회 <b>'+state.chances[0]+' : '+state.chances[1]+'</b></span><span>슈팅 <b>'+state.shots[0]+' : '+state.shots[1]+'</b></span>';}
function rangeLabel(values){const min=Math.min(...values),max=Math.max(...values);return min===max?String(min):min+'~'+max;}
function europeFullTimeLabel(result){const won=result?.winner===S.own;if(season.europe.stage<6)return won?'챔피언스리그 승리 · 승점 3':result?.winner===null?'챔피언스리그 무승부 · 승점 1':'챔피언스리그 패배 · 다음 경기를 준비하세요';return won?(season.europe.stage===7?S.club(S.own).short+', 유럽의 챔피언':'챔피언스리그 결승 진출'):'챔피언스리그 도전을 마쳤습니다';}
function renderResults(){const cupResult=cupOutcome(),won=cupResult?cupResult.winner===S.own:state.score[0]>state.score[1],segments=state.segments,pressMinutes=segments.filter(s=>s.tactic==='press').reduce((n,s)=>n+s.end-s.start,0),lowBlockMinutes=segments.filter(s=>s.tactic==='lowBlock').reduce((n,s)=>n+s.end-s.start,0),counter=segments.filter(s=>s.tactic==='counter'),counterMinutes=counter.reduce((n,s)=>n+s.end-s.start,0);let lessons=[];if(counter.length){const chances=counter.reduce((n,s)=>n+s.chances[0],0);lessons.push(`<li>역습 지시 ${counterMinutes}분 · 공격 기회 ${chances}회<small>해당 구간 시작 때 공격수 평균 속도는 ${rangeLabel(counter.map(s=>Math.round(s.rating.pace)))}이었습니다. 상대 수비 속도 ${rangeLabel(counter.map(s=>Math.round(s.rating.opponent.speed)))}와 비교해 속도 차이가 양수인 구간에만 역습 보너스를 반영했습니다.</small></li>`);}if(pressMinutes)lessons.push(`<li>전방 압박 ${pressMinutes}분<small>공격 기회 생성률은 기본 대비 18% 높였고, 상대 기회 생성률도 13% 높였습니다. 출전 선수의 체력 소모도 늘었습니다.</small></li>`);if(lowBlockMinutes)lessons.push(`<li>로우 블록 ${lowBlockMinutes}분<small>우리 찬스 비율은 14% 낮아지고 상대는 28% 낮아집니다. 수비 지표가 8% 오르며 체력 추가 소모는 없습니다.</small></li>`);const fwSub=state.decisions.find(d=>d.type==='sub'&&state.players[d.in].pos==='FW');if(fwSub){const p=state.players[fwSub.in],old=state.players[fwSub.out];lessons.push(`<li>${fwSub.minute}분, ${old.name} 대신 ${p.name}<small>속도 ${old.speed} → ${p.speed}, 결정력 ${old.attack} → ${p.attack}. 투입 후 ${p.minutes}분을 뛰었습니다. 빠른 발과 결정력의 차이를 함께 반영했습니다.</small></li>`);}if(!lessons.length)lessons.push('<li>균형 지시로 경기를 운영했습니다.<small>다음에는 상대의 느린 수비를 노리는 역습이나, 체력을 아끼는 교체를 비교해보세요.</small></li>');lessons.push('<li>선택은 기회를 바꾸고, 승패에는 우연도 작용합니다.<small>'+(season.competition==='europe'?'챔피언스리그 결과를 확정하면 대회 순위·진출 여부, 경기 수입과 출전 경험을 반영합니다.':cupResult?'컵 결과를 확정하면 진출 여부, 경기 수입과 출전 경험을 반영합니다.':'경기 기록을 확정하면 승점, 출전 경험과 체력 회복을 함께 반영합니다.')+'</small></li>');$('results').innerHTML=`<div class="results-title"><h2>${season.competition==='europe'?europeFullTimeLabel(cupResult):cupResult?(won?(season.cup.stage===2?'컵의 주인은 우리다.':'한 걸음 더, 다음 라운드.'): '컵의 도전은 여기까지.') :won?'작은 구단의 큰 승리.':state.score[0]===state.score[1]?'승점보다 남은 가능성.':'다음엔 다르게 해보자.'}</h2><span>${S.club(S.own).short} ${state.score[0]} : ${state.score[1]} ${S.opponentFor(season).short}</span></div>${cupKicks(cupResult)}${matchReviewMarkup(MatchReview.read(season,{source:'pending'}))}${healthReviewMarkup()}<div class="result-grid"><div><table class="stats-table"><thead><tr><th scope="col">경기 기록</th><th scope="col">${S.club(S.own).short}</th><th scope="col">${S.opponentFor(season).short}</th></tr></thead><tbody><tr><td>공격 기회</td><td>${state.chances[0]}</td><td>${state.chances[1]}</td></tr><tr><td>슈팅</td><td>${state.shots[0]}</td><td>${state.shots[1]}</td></tr><tr><td>득점 기대치</td><td>${state.xg[0].toFixed(2)}</td><td>${state.xg[1].toFixed(2)}</td></tr>${Matchday.facts(state).filter(row=>row.key!=="xg").map(row=>`<tr><td>${row.label}</td><td>${row.own}</td><td>${row.opponent}</td></tr>`).join("")}</tbody></table><p class="stats-caption">점유율은 중원 전력으로 추정합니다. xG는 실제 슈팅 확률의 합계이며, —는 해당 기록을 확인할 수 없다는 뜻입니다.</p></div><ul class="result-lessons">${lessons.join('')}</ul></div><button class="primary" id="replay">${season.competition==='europe'?"챔피언스리그 결과 확정 · 다음 일정":season.competition==='cup'?"컵 결과 확정 · 다음 일정":"결과 확정 · 다음 일정"}</button>`;$('replay').onclick=advanceSeason;}
function advanceSeason(){const previous=season;action(()=>{season=S.settle(season);clearMatchFeedback();state=season.match;selected=null;lastEvent=null;rotationNote='';view='club';});if(season!==previous)focusLatestMatchReview();}
function primary(){if(state?.phase==='full'){advanceSeason();return;}action(()=>{selected=null;advanceMatchWithFeedback();});if(state&&['half','late'].includes(state.phase)&&window.innerWidth<730)$('matchday-selection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function advanceMatchWithFeedback(){const from=state.logs.length;if(F.running(state)){if(state.paused){state.paused=false;movementStamp=performance.now();}else MatchFlow.advanceFive(state,playbackPrefs);}else F.begin(state);matchClock.reset();presentMatchEvents(state.logs.slice(from),true);}
function tone(kind){if(!soundOn)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume().catch(()=>{});const notes=kind==='goal'||kind==='preview'?[523,659,784]:kind==='concede'?[330,262]:kind==='save'?[659,880]:[330];for(let i=0;i<notes.length;i++){const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.frequency.value=notes[i];gain.gain.setValueAtTime(.045,audioCtx.currentTime+i*.12);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+i*.12+.13);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(audioCtx.currentTime+i*.12);osc.stop(audioCtx.currentTime+i*.12+.15);}}catch{}}
function drawField(){if(!state)return;const c=$('field'),r=PitchArt.measure(c,innerWidth+':'+innerHeight+':'+devicePixelRatio),d=Math.min(devicePixelRatio||1,2);if(!r.width)return;if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);}const ctx=c.getContext('2d');ctx.setTransform(d,0,0,d,0,0);const w=r.width,h=r.height;PitchArt.draw(ctx,w,h,d,season.league.division);drawMotionActors(ctx,w,h);}
$('open-match-review').onclick=()=>{if(typeof openMatchPopup==='function'){openMatchPopup('stats');return;}$('results').scrollIntoView({block:'start',behavior:'instant'});$('results').focus({preventScroll:true});};
let pitchDrag=null,pitchDragMoved=false;
$('players').addEventListener('pointerdown',event=>{if(typeof openMatchPopup==='function')return;const button=event.target.closest('[data-player]');if(!button||!editable()||F.running(state)&&!state.paused)return;const rect=$('pitch').getBoundingClientRect();pitchDrag={id:button.dataset.player,identity:state.players[button.dataset.player].identity,button,rect,startX:event.clientX,startY:event.clientY};pitchDragMoved=false;button.setPointerCapture?.(event.pointerId);});
$('players').addEventListener('pointermove',event=>{if(!pitchDrag)return;const dx=event.clientX-pitchDrag.startX,dy=event.clientY-pitchDrag.startY;if(!pitchDragMoved&&Math.hypot(dx,dy)<6)return;pitchDragMoved=true;event.preventDefault();const x=Math.max(7,Math.min(93,(event.clientX-pitchDrag.rect.left)/pitchDrag.rect.width*100)),y=Math.max(8,Math.min(92,(event.clientY-pitchDrag.rect.top)/pitchDrag.rect.height*100));pitchDrag.button.style.left=x+'%';pitchDrag.button.style.top=y+'%';customPositions[pitchDrag.identity]=[Math.round(x*10)/10,Math.round(y*10)/10];});
$('players').addEventListener('pointerup',()=>{if(!pitchDrag)return;if(pitchDragMoved){selected=pitchDrag.id;save();render();}pitchDrag=null;});
$('players').addEventListener('pointercancel',()=>{pitchDrag=null;pitchDragMoved=false;});
$('mobile-tactics-dock').addEventListener('click',event=>{const formation=event.target.closest('[data-mobile-formation]'),tactic=event.target.closest('[data-mobile-tactic]');if(formation&&!formation.disabled){action(()=>{F.setFormation(state,formation.dataset.mobileFormation);customPositions={};selected=null;});return;}if(tactic&&!tactic.disabled){action(()=>{pauseForPlanning();collapseTacticsBoard();F.setTactic(state,tactic.dataset.mobileTactic);});}});
$('pitch-swap-options').addEventListener('click',event=>{const button=event.target.closest('[data-pitch-swap]');if(!button||button.disabled||!selected)return;action(()=>{const change=F.swap(state,selected,button.dataset.pitchSwap);presentSubstitution(change);const oldIdentity=state.players[selected]?.identity;selected=button.dataset.pitchSwap;if(oldIdentity&&customPositions[oldIdentity]){customPositions[state.players[selected].identity]=customPositions[oldIdentity];delete customPositions[oldIdentity];}});});
$('players').addEventListener('click',e=>{if(typeof openMatchPopup==='function')return;if(pitchDragMoved){pitchDragMoved=false;return;}const b=e.target.closest('[data-player]');if(b&&editable()){pauseForPlanning();collapseTacticsBoard();selected=selected===b.dataset.player?null:b.dataset.player;save();render();$('players').querySelector('[data-player="'+b.dataset.player+'"]')?.focus({preventScroll:true});if(selected&&typeof openMatchPopup==='function'){openMatchPopup('roster',b);}else if(selected&&innerWidth<730){$('pitch-player-tools').scrollIntoView({block:'nearest',behavior:'instant'});$('player-role-select')?.focus({preventScroll:true});}}});$('bench').addEventListener('click',e=>{const b=e.target.closest('[data-bench]');if(!b)return;action(()=>{if(!selected)throw Error('먼저 경기장의 선발 선수를 선택하세요.');const change=F.swap(state,selected,b.dataset.bench);presentSubstitution(change);selected=b.dataset.bench;rotationNote='';});});$('formation').addEventListener('change',e=>action(()=>{F.setFormation(state,e.target.value);customPositions={};selected=null;rotationNote='';}));$('tactic-options').addEventListener('click',e=>{const b=e.target.closest('[data-tactic]');if(b){action(()=>{pauseForPlanning();collapseTacticsBoard();F.setTactic(state,b.dataset.tactic);});$('tactic-options').querySelector('[data-tactic="'+b.dataset.tactic+'"]')?.focus({preventScroll:true});}});$('primary').onclick=primary;$('pause').onclick=()=>{if(!state||!F.running(state))return;if(state.paused)action(()=>{presentMatchEvents(MatchFlow.advanceFive(state,playbackPrefs),true);selected=null;matchClock.reset();});else toggleMatchPlanning(false);};$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent=soundOn?'소리 끄기':'소리 켜기';$('sound').setAttribute('aria-pressed',soundOn);if(soundOn)tone(false);};new ResizeObserver(drawField).observe($('pitch'));
setInterval(()=>{const active=appSessionStarted&&!practiceSession&&!!state&&F.running(state)&&!state.paused&&!document.hidden&&view==='match';if(active&&motionEnabled()&&movementHighlightPending())return;if(!matchClock.due(performance.now(),active,playbackPrefs.speed))return;const events=MatchFlow.step(state,playbackPrefs);presentMatchEvents(events);save();render();if(typeof openMatchPopup==='undefined'&&['half','late'].includes(state.phase)&&window.innerWidth<730)$('matchday-selection').scrollIntoView({behavior:motionEnabled()?'smooth':'instant',block:'start'});},100);
let frame=0,lastDrawStamp=0;function animate(now=performance.now()){if(movementShouldAnimate()&&now-lastDrawStamp>=1000/30){drawField();lastDrawStamp=now;}frame=requestAnimationFrame(animate);}animate();window.addEventListener('pagehide',()=>{save();cancelAnimationFrame(frame);});window.addEventListener('pageshow',e=>{if(e.persisted)animate();});render();
if(document.modelContext?.registerTool){const tools=[{name:'read_practice_state',description:'Read the isolated touchline practice and actual remaining-minute events. Never changes club funds, player growth or league records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>practiceSession?Practice.read(practiceSession):{valid:false,reason:'작전 연습이 열려 있지 않습니다.'}},{name:'read_coach_guide',description:'Read next club action and confirmed experience to the next skill growth. Never starts or trains a player.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>CoachGuide.read(season)},{name:'read_tactics_board',description:'Read current lineup condition, opponent comparisons, four tactic snapshot indicators and analytical fatigue. Preview only: never changes tactics or advances the match.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>readTacticsPlan()},{name:'read_match_review',description:'Read a finished unconfirmed match or the latest confirmed recap: actual identity-based goals, assists, minutes, growth, health and cash. Never settles or advances a match.',inputSchema:{type:'object',properties:{source:{type:'string',enum:['latest','pending']}},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>MatchReview.read(season,{source:input.source||'latest'})},{name:'read_player_details',description:'Read an owned player or discovered candidate’s actual skills, condition, growth and confirmed season records by identity. Never trains or recruits.',inputSchema:{type:'object',properties:{identity:{type:'string'}},required:['identity'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>PlayerDetails.read(season,input.identity)},{name:'read_player_development',description:'Read confirmed experience, next growth milestone and available coach training recommendation for a current player.',inputSchema:{type:'object',properties:{slot:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>PlayerDevelopment.analyze(season,input.slot||individualTrainingSlot)},{name:'read_match_movement',description:'Read display-only 2D player and ball positions and preview state. Never advances a match.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>movementSnapshot()},{name:'read_training_centre',description:'Read actual squad training availability, current energy, primary skills, confirmed growth milestones and coach recommendations. Filters only; never trains, spends or advances time.',inputSchema:{type:'object',properties:{position:{type:'string',enum:['all','GK','DEF','MID','FW']},query:{type:'string'},sort:{type:'string',enum:['recommended','potential','minutes']}},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>TrainingCentre.read(season,input)},{name:'read_individual_training',description:'Read exact individual training gain, fatigue, weekly availability and player identity.',inputSchema:{type:'object',properties:{slot:{type:'string'},focus:{type:'string',enum:['technique','pace','fitness','recovery']}},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>Training.preview(season,input.slot||individualTrainingSlot,input.focus||individualTrainingFocus)},{name:'train_individual_player',description:'Apply individual training instead of this week’s squad training, before a league match only.',inputSchema:{type:'object',properties:{slot:{type:'string'},focus:{type:'string',enum:['technique','pace','fitness','recovery']}},required:['slot','focus'],additionalProperties:false},execute:input=>{const result=Training.train(season,input.slot,input.focus);save();render();return result;},annotations:{destructiveHint:false}},{name:'read_match_feedback',description:'Read presentation preferences and the latest display-only match moment; never changes gameplay.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>feedbackSnapshot()},{name:'read_player_records',description:'Read identity-based goals, assists, starts, actual minutes and goalkeeper clean sheets from confirmed games; excludes shootout goals.',inputSchema:{type:'object',properties:{competition:{type:'string',enum:['all','league','cup','europe']},year:{type:'integer',minimum:1}},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>ST.summary(season,input.competition||'all',input.year||season.year)},{name:'read_health_state',description:'Read injured players, current energy, remaining games to rest and last post-match health report.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({year:season.year,health:season.health,players:Object.values(season.squad).map(p=>({id:p.id,identity:p.identity,name:p.name,pos:p.pos,injury:p.injury,energy:loadEnergy(p),starting:state?.lineup.includes(p.id)||false}))})},{name:'rotate_starting_eleven',description:'Select fit starters by energy within the current formation before kickoff; keeps the tactic, funds and weekly actions.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{const result=H.rotate(season);selected=null;rotationNote='체력 우선 자동 선발을 적용했습니다.';save();render();return {rotation:result,match:snapshot()};}},{name:'read_cup_state',description:'Read the current Cup knockout bracket, deterministic penalty result and trophy records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({competition:season.competition,cup:season.cup,status:cupStatus(),fullTimeResult:season.competition==='cup'?cupOutcome():null,trophies:cupRecords()})},{name:'read_europe_state',description:'Read Champions League qualification, group standings, fixtures, results and current stage. Never advances time.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({competition:season.competition,europe:season.europe,status:europeStatus(),groups:season.europe.enabled?[Europe.standings(season,0),Europe.standings(season,1)]:[],fullTimeResult:season.competition==='europe'?cupOutcome():null})},{name:'read_club_life',description:'Read saved player talks, current press questions and fictional club articles derived from actual match records. Never changes confidence or answers interviews.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({talk:ClubLife.talkStatus(season),press:ClubLife.pressStatus(season),news:ClubLife.news(season)})},{name:'read_academy_state',description:'Read discovered youth player profiles, completed-minute development missions and club funds.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({year:season.year,round:season.round+1,finance:{balance:season.finance.balance,wages:clubWeeklyWages()},progress:C.progress(season),missions:season.career.missions,reports:season.career.reports.map(r=>({...r,players:r.candidates.map(id=>F.identityProfile(id))}))})},{name:'scout_youth',description:'Spend the current division’s published scouting fee to discover three youth players at a chosen position once per half-season before the match.',inputSchema:{type:'object',properties:{position:{type:'string',enum:['GK','DEF','MID','FW']}},required:['position'],additionalProperties:false},execute:input=>{season=S.scout(season,input.position);state=season.match;view='academy';save();render();return {reports:season.career.reports,balance:season.finance.balance};}},{name:'read_campaign_backup',description:'Read only this football campaign as a portable save file. No practice history or other browser data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>CampaignFile.stringify(currentCampaignPayload())},{name:'read_season_state',description:'Read league standings, current round and squad growth in this local prototype.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({year:season.year,round:season.round+1,finished:S.ready(season),league:season.league,movement:S.movement(season),competition:season.competition,trained:season.trained,finance:{balance:season.finance.balance,wages:clubWeeklyWages()},table:S.standings(season).map(c=>({name:c.name,rank:c.rank,points:c.points,played:c.played})),squad:Object.values(season.squad).map(p=>({id:p.id,identity:p.identity,name:p.name,xp:p.xp,potential:p.potential,wage:p.wage,primary:p[S.primaryKey(p)]}))})},{name:'train_squad',description:'Apply one weekly training before the match. Technique, pace, fitness or recovery. Changes squad skills and energy.',inputSchema:{type:'object',properties:{focus:{type:'string',enum:['technique','pace','fitness','recovery']}},required:['focus'],additionalProperties:false},execute:input=>{S.train(season,input.focus);save();render();return snapshot();}},{name:'confirm_match_result',description:'Confirm the finished current match, update league standings, grow players and advance to the next round. Fails before full time.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{season=S.settle(season);clearMatchFeedback();state=season.match;selected=null;lastEvent=null;rotationNote='';view='club';save();render();focusLatestMatchReview();return snapshot();}},{name:'start_next_season',description:'Start the next season after the league, Cup and Champions League are complete, keeping squad growth and history.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{season=S.nextSeason(season);clearMatchFeedback();lastEvent=null;state=season.match;view='club';selected=null;rotationNote='';save();render();return snapshot();}},{name:'set_match_playback',description:'Choose slow, normal or fast playback and optional 65-minute coach pause. Does not advance the match.',inputSchema:{type:'object',properties:{speed:{type:'string',enum:['slow','normal','fast']},coachPause65:{type:'boolean'}},additionalProperties:false},execute:input=>{playbackPrefs=MatchFlow.normalize({...playbackPrefs,...input});matchClock.reset();save();renderMatchControls();renderTacticsBoard();return {...playbackPrefs};}},{name:'pause_match_for_planning',description:'Pause a running match at its current minute to compare tactics or make substitutions. Never advances time.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{pauseForPlanning();save();render();return snapshot();}},{name:'read_match_state',description:'Read the current football match, line-up and available bench players.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>snapshot()},{name:'set_match_tactic',description:'Choose press, balanced, counter or lowBlock before or at any minute of a supported match; pauses for a deliberate decision. Changes the visible match instruction.',inputSchema:{type:'object',properties:{tactic:{type:'string',enum:['press','balanced','counter','lowBlock']}},required:['tactic'],additionalProperties:false},execute:input=>{pauseForPlanning();F.setTactic(state,input.tactic);save();render();return snapshot();}},{name:'substitute_match_player',description:'Replace a starting player with a same-position bench player. During the match this consumes one of five substitutions, subject to three in-play windows.',inputSchema:{type:'object',properties:{outId:{type:'string'},inId:{type:'string'}},required:['outId','inId'],additionalProperties:false},execute:input=>{pauseForPlanning();const change=F.swap(state,input.outId,input.inId);presentSubstitution(change);save();render();return snapshot();}},{name:'advance_match_phase',description:'Start or resume the match, or view at most five minutes and pause for the next decision. Does not restart a finished match.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>{if(!state||state.phase==='full')throw Error('The match is finished.');advanceMatchWithFeedback();save();render();return snapshot();}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}

